from author_csharp_v2 import *

unit(1,
"فایل متن برنامه را نگه می‌دارد و پوشه فایل‌های مرتبط را کنار هم جمع می‌کند. ویرایشگر برای تغییر فایل است؛ ترمینال دستور ابزارها را اجرا می‌کند. SDK ابزار ساخت را همراه دارد؛ Runtime برای اجرای برنامهٔ ساخته‌شده است. در یک پوشهٔ تازه dotnet new console پروژه می‌سازد، dotnet build خطاهای ساخت را بررسی می‌کند و dotnet run برنامه را می‌سازد و اجرا می‌کند. Console نام ابزار ورودی‌وخروجی متن و WriteLine فرمان نوشتن یک خط است. در top-level statements دستورها بدون نوشتن کلاس و Main صریح قرار می‌گیرند. متن داخل گیومه داده است؛ نام فرمان بیرون آن قرار دارد.",
'Console.WriteLine("Hello");', 'Hello',
("فایل Program.cs را ذخیره کرده‌ای. کدام دستور برنامه را اجرا می‌کند؟", "dotnet run", "dotnet restore فقط", "نوشتن نام پوشه", "build خروجی قابل اجرا می‌سازد؛ run آن را اجرا می‌کند. restore وابستگی‌ها را آماده می‌کند."),
constraints("اولین اجرای سالم", "در پوشهٔ خالی، مراحل را با رعایت وابستگی‌ها بچین. در این تمرین، پیش از run یک بار build مستقل انجام بده تا خروجی ساخت و اجرای برنامه را جدا ببینی. خود dotnet run نیز به‌صورت پیش‌فرض ساخت را انجام می‌دهد.",
["نصب SDK", "dotnet new console", "ویرایش و ذخیرهٔ Program.cs", "dotnet build", "dotnet run و دیدن پیام"], [[0,1],[1,2],[2,3],[3,4]]),
"در پوشه‌ای تازه پروژهٔ console بساز که دو خط Ready و C# را چاپ کند. یک بار فقط build و یک بار run انجام بده؛ فرق خروجی ابزارها را ثبت کن.",
'Console.WriteLine("Ready");\nConsole.WriteLine("C#");',
"خروجی اجرای برنامه دقیقاً دو خط Ready و C# است. موفقیت build با متن چاپ‌شدهٔ run اشتباه نشود؛ SDK نصب و فایل پیش از اجرا ذخیره شده باشد.")
UNITS[1]["summary"] += "\n\nشروع عملی:\n۱. نسخهٔ SDK برای .NET 10 را نصب کن؛ Runtime به‌تنهایی ابزار ساخت ندارد. با dotnet --list-sdks وجود نسخهٔ 10 را بررسی کن.\n۲. در ترمینال و پوشهٔ موردنظرت dotnet new console -n FirstApp را اجرا کن؛ سپس با cd FirstApp وارد پوشهٔ پروژه شو.\n۳. فایل Program.cs را در ویرایشگر باز کن، متن داخل گیومه را عوض کن و فایل را ذخیره کن.\n۴. در همان پوشه dotnet build و سپس dotnet run را اجرا کن. build پیام ابزار ساخت می‌دهد؛ متن برنامه را run چاپ می‌کند. در اجرای معمول، run ساخت لازم را هم انجام می‌دهد."

unit(2,
"expression مقدار تولید می‌کند؛ statement یک دستور کامل است. در Console.WriteLine(2 + 3); جمع یک expression و کل فراخوانی یک statement است. شناسه نام متغیر یا عضو است؛ keyword مثل int معنای از پیش تعیین‌شده دارد. C# به بزرگی حروف حساس است: Console و console یکی نیستند. literal مثل 3 یا متن داخل گیومه مستقیماً داده را بیان می‌کند. سمی‌کالن پایان بسیاری از دستورها و آکولاد مرز بلوک است. comment با // یا /* */ توضیح خواننده است و اجرا نمی‌شود. diagnostic پیام ابزار ساخت است؛ ابتدا اولین پیام و محل آن را اصلاح کن، چون یک خطای ابتدایی ممکن است پیام‌های بعدی بسازد.",
'// A statement containing an expression\nConsole.WriteLine(2 + 3);', '5',
("با خطای The name 'console' does not exist چه اصلاحی لازم است؟", "console را به Console تغییر بده.", "Runtime را حذف کن.", "عدد را داخل comment بگذار.", "شناسه‌ها به بزرگی حروف حساس‌اند؛ Console نام درست نوع کتابخانه است."),
repair("تعمیر یک نام", "فقط نام نوع را اصلاح کن تا متن OK چاپ شود. سمی‌کالن و متد آماده‌اند.", ["console", "Console", "CONSOLE"], [0], ["نام شناخته می‌شود", "متن OK چاپ می‌شود"], [([0],[False,False]),([1],[True,True]),([2],[False,False])], code='TYPE.WriteLine("OK");'),
"کدی بنویس که حاصل 4 + 6 را چاپ کند. سپس عمداً سمی‌کالن را بردار، اولین diagnostic را ثبت و خطا را اصلاح کن. یک comment مفید اضافه کن.",
'// The receipt contains ten items.\nConsole.WriteLine(4 + 6);',
"نسخهٔ سالم 10 چاپ کند. نسخهٔ بدون سمی‌کالن باید هنگام build رد شود؛ توضیح تفاوت expression و statement با همین مثال همراه باشد.")

unit(3,
"متغیر نامی برای نگهداری یک مقدار با نوع مشخص است. تعریف، نوع و نام را معرفی می‌کند؛ انتساب مقدار را عوض می‌کند. var نوع را از مقدار اولیه در زمان کامپایل استنتاج می‌کند و بعداً نوع عوض نمی‌شود. const مقدار ثابت زمان کامپایل دارد و دوباره قابل انتساب نیست. متغیر محلی پیش از خواندن باید در همهٔ مسیرهای ممکن مقدار گرفته باشد؛ این قاعده definite assignment است. default(int) صفر، default(bool) نادرست و default(char) نویسهٔ صفر است، ولی متغیر محلی بدون انتساب خودکار قابل خواندن نمی‌شود. int برای عدد صحیح، decimal برای محاسبهٔ ده‌دهی و char برای یک واحد UTF-16 است. نام فقط راه دسترسی به مقدار است و خودش مقدار نیست.",
'int score = 2;\nvar copy = score;\nscore = 7;\nConsole.WriteLine(copy);', '2',
("var count = 2; سپس count = \"two\" چه می‌شود؟", "خطای کامپایل؛ نوع count همچنان int است.", "نوع count به string تبدیل می‌شود.", "عدد 2 خودکار حذف می‌شود و کد همیشه معتبر است.", "var استنتاج نوع ایستاست؛ انتساب تازه باید با همان نوع سازگار باشد."),
simulation("ردگیری انتساب", "از n=1 با اقدام‌های مجاز به n=4 برس. نمایش‌ها وضعیت آموزشی‌اند، نه اجرای کد کاربر.", ["n += 1", "n *= 2"], ["n=1","n=2","n=3","n=4"], [[1,1],[2,3],[3,-1],[-1,-1]], [3], limit=3),
"دو متغیر عددی بساز. مقدار اول را در دوم کپی کن و سپس اولی را تغییر بده. نشان بده دومی مستقل مانده است. یک const و مقدار default(bool) را هم چاپ کن.",
'int first = 4;\nint second = first;\nfirst = 9;\nconst int limit = 10;\nConsole.WriteLine($"{first},{second},{limit},{default(bool)}");',
"خروجی 9,4,10,False باشد؛ تغییر first مقدار second را عوض نکند. const پس از تعریف تغییر نکند و هیچ متغیر محلی پیش از انتساب خوانده نشود.")

unit(4,
"تقسیم دو عدد صحیح بخش کسری را حذف می‌کند: 7 / 2 برابر 3 است. % باقی‌مانده می‌دهد. پرانتز بر اولویت ضرب و جمع مقدم است؛ ++ و انتساب مرکب مقدار متغیر را تغییر می‌دهند. تبدیل ضمنی فقط برای مسیرهای مجاز زبان بدون cast نوشته می‌شود، اما تبدیل صریح ممکن است داده از دست بدهد. checked سرریز عملیات صحیح غیرثابت را به exception تبدیل می‌کند؛ unchecked اجازهٔ پیچیدن در محدودهٔ نوع صحیح را می‌دهد. decimal با سرریز حتی در unchecked هم exception می‌دهد و رفتار آن را نباید با int یکی دانست. پسوند m نوع decimal و L نوع long را مشخص می‌کند. تبدیل double به int بخش کسری را نگه نمی‌دارد.",
'int whole = 7 / 2;\nint remainder = 7 % 2;\nConsole.WriteLine($"{whole},{remainder}");', '3,1',
("برای تقسیم 7 بر 2 با نتیجهٔ کسری چه می‌کنی؟", "پیش از تقسیم یکی از عملوندها را به double تبدیل می‌کنم.", "پس از تقسیم صحیح، حاصل را به double تبدیل می‌کنم.", "از % به جای / استفاده می‌کنم.", "تبدیل پس از 7 / 2 عدد 3 را به 3.0 تبدیل می‌کند؛ بخش کسری قبلاً حذف شده است."),
counter("شکستن ادعای تقسیم", "ادعا: برای هر n مثبت، n / 2 در C# همان نصف دقیق ریاضی است. ورودی نقض‌کننده را آزمایش کن.", ["n=2","n=3","n=5"], [("1","1",False,"عدد زوج نصف صحیح دارد."),("1","1.5",True,"تقسیم صحیح بخش کسری را حذف کرد."),("2","2.5",True,"یک ضدنمونهٔ دیگر؛ تمام ورودی‌های فرد این دامنه معتبرند.")]),
"قیمت واحد 12.5m و تعداد 3 را محاسبه کن؛ سپس تقسیم صحیح 9/2 و تقسیم اعشاری 9m/2 را مقایسه کن. سرریز int.MaxValue+1 را یک بار checked و یک بار unchecked با متغیر آزمایش کن.",
'decimal total = 12.5m * 3;\nConsole.WriteLine(total);\nConsole.WriteLine(9 / 2);\nConsole.WriteLine(9m / 2);\nint max = int.MaxValue;\ntry { Console.WriteLine(checked(max + 1)); }\ncatch (OverflowException) { Console.WriteLine("overflow"); }\nConsole.WriteLine(unchecked(max + 1));',
"مبلغ 37.5، تقسیم‌ها 4 و 4.5 باشند؛ checked خطا و unchecked مقدار -2147483648 بدهد. محاسبهٔ پول با decimal انجام شود.")

unit(5,
"string دنبالهٔ متن و char یک واحد UTF-16 است؛ متن حتی تک‌حرفی داخل گیومهٔ دوتایی و char داخل گیومهٔ تکی نوشته می‌شود. + متن‌ها را متصل و $ پیش از رشته مقدارها را با interpolation جای‌گذاری می‌کند. :F2 دو رقم اعشار در نمایش می‌دهد و به culture وابسته است. escape مثل \\n خط تازه، \\t تب و \\e نویسهٔ Escape می‌سازد. رشتهٔ verbatim با @ بک‌اسلش را عادی می‌گیرد؛ raw string با سه گیومه برای متن و گیومه‌های فراوان مناسب است. string تغییرناپذیر است: Replace رشتهٔ تازه برمی‌گرداند. Length تعداد واحدهای UTF-16 است و همیشه تعداد نویسهٔ دیده‌شده نیست. متن خالی با یک فاصله تفاوت دارد.",
'string name = "Ada";\nConsole.WriteLine($"Hi {name}");\nConsole.WriteLine("".Length);', 'Hi Ada\n0',
("s.Replace(\"a\", \"b\"); را بدون انتساب اجرا می‌کنی. s چه می‌شود؟", "مقدار s تغییر نمی‌کند؛ نتیجهٔ جدید باید دریافت شود.", "خود رشتهٔ s درجا تغییر می‌کند.", "همیشه exception رخ می‌دهد.", "رشته تغییرناپذیر است؛ s = s.Replace(...) مرجع s را به نتیجهٔ تازه می‌دهد."),
groups("خانوادهٔ متن", "کارت‌ها را بر اساس نوع literal به دو گروه تقسیم کن؛ منظور شکل نوشتن C# است.", ["string literal","char literal"], [['"A"','""','@"C:\\work"'],["'A'","'\\n'","' '"]]),
"رسیدی دوخطی برای نام Book و مبلغ 12.5m بساز. عدد با دو رقم اعشار و InvariantCulture نمایش داده شود. طول متن خالی و یک فاصله را هم مقایسه کن.",
'using System.Globalization;\nstring item = "Book";\ndecimal price = 12.5m;\nConsole.WriteLine($"Item: {item}");\nConsole.WriteLine("Price: " + price.ToString("F2", CultureInfo.InvariantCulture));\nConsole.WriteLine($"{\"\".Length},{\" \".Length}");',
"خروجی Item: Book و Price: 12.50 مستقل از فرهنگ دستگاه باشد؛ طول‌ها 0 و 1 باشند. متن چندخطی با خط تازهٔ واقعی ساخته شود.")

unit(6,
"مقایسه‌ها bool تولید می‌کنند. == برابری، != نابرابری و < یا >= مرز عددی را بررسی می‌کنند. && فقط وقتی سمت چپ درست باشد سمت راست را ارزیابی می‌کند؛ || فقط وقتی سمت چپ نادرست باشد سراغ راست می‌رود. این رفتار short-circuit نام دارد و می‌تواند از تقسیم بر صفر یا دسترسی نامعتبر جلوگیری کند. & و | روی bool هر دو سمت را ارزیابی می‌کنند. ! نتیجه را معکوس می‌کند. پرانتز شرط‌های ترکیبی را خوانا می‌کند و از اتکا به حفظ اولویت جلوگیری می‌کند. عملگر ?: بر اساس شرط یکی از دو expression را انتخاب می‌کند؛ فقط شاخهٔ انتخاب‌شده ارزیابی می‌شود.",
'int count = 0;\nbool valid = count != 0 && 10 / count > 1;\nConsole.WriteLine(valid);', 'False',
("برای شرط پذیرش سن از 18 تا 65 شامل دو مرز کدام درست است؟", "age >= 18 && age <= 65", "age > 18 && age < 65", "age >= 18 || age <= 65", "بازهٔ بسته به && و دو مقایسهٔ شامل مرز نیاز دارد؛ || تقریباً همهٔ اعداد را قبول می‌کند."),
counter("ضدنمونهٔ OR", "ادعا: شرط age >= 18 || age <= 65 فقط سن 18 تا 65 را می‌پذیرد.", ["age=30","age=10","age=80"], [("پذیرفته","پذیرفته",False,"این ورودی داخل بازه است."),("پذیرفته","رد",True,"10 از 65 کوچک‌تر است و OR را درست می‌کند."),("پذیرفته","رد",True,"80 از 18 بزرگ‌تر است و OR را درست می‌کند.")]),
"شرط پذیرش سن 18 تا 65 را بنویس. ورودی‌های 17،18،65،66 را بررسی کن. شرط امنی هم برای تقسیم 12 بر مقدار ورودی بنویس که صفر را بدون exception رد کند.",
'foreach (int age in new[] {17,18,65,66})\n    Console.WriteLine(age >= 18 && age <= 65);\nint divisor = 0;\nConsole.WriteLine(divisor != 0 && 12 / divisor > 0);',
"چهار نتیجه False,True,True,False باشند. ورودی صفر به سمت راست تقسیم وارد نشود. توضیح جدول حالت‌ها تفاوت && و || را روشن کند.")

unit(7,
"if نخستین شرط درست را اجرا می‌کند؛ else if و else شاخه‌های بعدی همان تصمیم‌اند. شرط‌های تو‌در‌تو برای وابستگی واقعی تصمیم‌ها مفیدند، اما ترتیب شاخه‌ها مهم است: شرط عام می‌تواند شرط خاص را بی‌اثر کند. switch statement چند statement اجرا می‌کند؛ caseها مسیرهای مجزا و default مسیر سایر مقدارهاست. switch expression یک مقدار می‌سازد و معمولاً با _ پوشش بقیه را کامل می‌کند. در این مرحله برچسب ثابت کافی است؛ الگوهای پیشرفته بعداً می‌آیند. هر دو روش باید برای مرز بازه و مقدار ناشناخته رفتار مشخص داشته باشند.",
'int quantity = 10;\nint discount = quantity >= 10 ? 20 : 0;\nConsole.WriteLine(discount);', '20',
("اول شرط x >= 0 و بعد else if (x >= 10) قرار دارد. مشکل چیست؟", "شاخهٔ دوم برای 10 و بیشتر هرگز انتخاب نمی‌شود.", "همهٔ شرط‌ها همزمان اجرا می‌شوند.", "باید else را با while عوض کرد.", "ترتیب شرط‌ها باید از خاص به عام باشد؛ شاخهٔ اول مقدارهای شاخهٔ دوم را هم می‌گیرد."),
repair("تعمیر مرز تخفیف", "قرارداد: تعداد 10 و بالاتر، 20 درصد تخفیف؛ کمتر از آن صفر. فقط عملگر را عوض کن.", [">",">=","=="], [0], ["تعداد 9: صفر", "تعداد 10: بیست", "تعداد 11: بیست"], [([0],[True,False,True]),([1],[True,True,True]),([2],[True,True,False])], code="int discount = quantity OP 10 ? 20 : 0;"),
"متد PriceBand برای عدد منفی Invalid، صفر Free و مثبت Paid بدهد. همین تصمیم را با if و switch expression بنویس و نتیجه‌ها را برای -1،0،2 مقایسه کن.",
'foreach (int value in new[] {-1,0,2})\n{\n    string byIf;\n    if (value < 0) byIf = "Invalid";\n    else if (value == 0) byIf = "Free";\n    else byIf = "Paid";\n    string bySwitch = value switch { < 0 => "Invalid", 0 => "Free", _ => "Paid" };\n    Console.WriteLine($"{byIf},{bySwitch}");\n}',
"هر دو پیاده‌سازی خروجی یکسان و پوشش کامل داشته باشند. شاخهٔ مثبت نباید صفر را ببلعد. pattern مقایسه‌ای این مثال فقط صورت کوتاه همان شرط معرفی‌شده است.")

unit(8,
"حلقه اجرای دستورها را تکرار می‌کند. for مقدار اولیه، شرط ادامه و تغییر شمارنده را کنار هم دارد؛ while شرط را پیش از بدنه می‌سنجد. do/while حداقل یک بار بدنه را اجرا می‌کند و بعد شرط را بررسی می‌کند. break نزدیک‌ترین حلقه را تمام و continue باقی بدنهٔ همان دور را رد می‌کند. شمارنده تعداد دور و جمع‌کننده حاصل تدریجی را نگه می‌دارد. برای جلوگیری از حلقهٔ بی‌پایان، بررسی کن در هر مسیر از جمله continue، وضعیت به پایان نزدیک شود. ردگیری دستی یعنی نوشتن مقدار متغیرها پس از هر دور، بدون حدس از روی ظاهر کد.",
'int sum = 0;\nfor (int i = 1; i <= 3; i++) sum += i;\nConsole.WriteLine(sum);', '6',
("اگر شرط اولیه false باشد، کدام حلقه یک بار اجرا می‌شود؟", "do/while", "while", "for با همان شرط false", "در do/while آزمون شرط پس از بدنه انجام می‌شود؛ دو شکل دیگر ممکن است صفر دور داشته باشند."),
simulation("جمع‌کنندهٔ سه قدم", "سه بار اقدام جمع دور بعد را انجام بده. هدف sum=6 و i=4 است؛ ترتیب مقداردهی شمارنده حفظ می‌شود.", ["sum += i; i++", "i++ بدون جمع"], ["i=1,sum=0","i=2,sum=1","i=3,sum=3","i=4,sum=6","جمع ناقص"], [[1,4],[2,4],[3,4],[-1,-1],[-1,-1]], [3], limit=3),
"جمع اعداد 1 تا n را با for و while بنویس. n=0 و n=4 را تست کن. جداگانه نشان بده do/while با شرط false یک بار اجرا می‌شود.",
'foreach (int n in new[] {0,4})\n{\n    int a=0; for(int i=1;i<=n;i++) a+=i;\n    int b=0,j=1; while(j<=n) { b+=j; j++; }\n    Console.WriteLine($"{a},{b}");\n}\nint runs=0; do { runs++; } while(false);\nConsole.WriteLine(runs);',
"برای صفر 0,0 و برای چهار 10,10 چاپ شود؛ do/while یک دور داشته باشد. شمارنده در تمام مسیرها به پایان نزدیک شود.")

unit(9,
"آرایه چند مقدار هم‌نوع با طول ثابت نگه می‌دارد. new int[3] سه عنصر صفر می‌سازد؛ initializer می‌تواند مقدارهای اولیه را تعیین کند. index از صفر شروع می‌شود و آخرین index معتبر Length-1 است. Length تعداد عناصر است و خودش index قابل دسترسی نیست. آرایهٔ خالی Length صفر دارد؛ کمینهٔ آن بدون قرارداد مشخص وجود ندارد. دو متغیر آرایه می‌توانند به یک آرایه اشاره کنند؛ تغییر عنصر از یکی در دیگری هم دیده می‌شود. این اشتراک را با کپی هر عنصر اشتباه نگیر. برای min/max بدون LINQ، نخست حالت خالی را جدا کن و سپس از اولین عنصر مقدار اولیه بگیر.",
'int[] values = {4, 7};\nint[] other = values;\nother[0] = 9;\nConsole.WriteLine(values[0]);', '9',
("برای آرایهٔ دارای Length=3 کدام index نامعتبر است؟", "3", "0", "2", "محدودهٔ معتبر 0 تا Length-1 است؛ شرط پیمایش i < Length است."),
counter("شکار آخرین خانه", "ادعا: حلقهٔ for با شرط i <= values.Length برای تمام آرایه‌ها ایمن است.", ["آرایهٔ خالی", "آرایهٔ [7]", "شرط i < Length برای [7]"], [("تلاش برای index صفر و خطا","بدون خطا",True,"حتی در آرایهٔ خالی 0<=0 درست است."),("در index یک خطا","بدون خطا",True,"Length آخرین index نیست."),("خواندن فقط index صفر","بدون خطا",False,"شرط سخت‌گیرانهٔ < درست است.")]),
"برای آرایهٔ [-3,7,2] کمینه و بیشینه را بدون LINQ پیدا کن. آرایهٔ خالی را بدون خواندن index صفر با پیام Empty مدیریت کن.",
'foreach (int[] values in new[] { new[] {-3,7,2}, Array.Empty<int>() })\n{\n    if (values.Length == 0) { Console.WriteLine("Empty"); continue; }\n    int min=values[0], max=values[0];\n    for(int i=1;i<values.Length;i++) { if(values[i]<min) min=values[i]; if(values[i]>max) max=values[i]; }\n    Console.WriteLine($"{min},{max}");\n}',
"نتیجه -3,7 و سپس Empty باشد. از صفر به‌عنوان کمینهٔ اولیه استفاده نشود؛ آرایهٔ فقط منفی هم آزموده شود.")

unit(10,
"foreach عناصر را بدون index دستی می‌خواند؛ متغیر پیمایش را نمی‌توان به‌جای خانهٔ آرایه دوباره مقداردهی کرد. برای تغییر عنصر از index یا مرجع مجاز استفاده کن. آرایهٔ مستطیلی int[,] ابعاد ثابت دارد و GetLength بعد دلخواه را می‌دهد؛ آرایهٔ jagged یعنی آرایه‌ای از آرایه‌ها که طول سطرهایش می‌تواند متفاوت باشد. حلقهٔ تو‌در‌تو سطر و ستون را می‌پیماید. ^1 یک خانه از انتها و .. برش با انتهای غیرشامل می‌سازد. ^0 موقعیت پایان است و برای خواندن عنصر معتبر نیست. برش آرایه آرایهٔ تازه می‌سازد؛ آن را با viewهای Span در بخش پیشرفته یکی ندان.",
'int[] scores = {2,4,6};\nConsole.WriteLine(scores[^1]);\nConsole.WriteLine(scores[1..].Length);', '6\n2',
("در jagged array برای پیمایش سطر دوم طول کدام را می‌خوانی؟", "rows[1].Length", "همیشه rows.Length", "همیشه rows[0].Length", "هر سطر آرایهٔ مستقل با طول خودش است؛ تعداد سطرها طول هر سطر نیست."),
spectrum("هزینهٔ پیمایش جدول", "جدول مستطیلی 3 سطر و 4 ستون دارد. دو حلقه هر خانه را دقیقاً یک بار می‌خوانند.", "معیار تعداد خواندن خانه‌هاست؛ هزینهٔ مقایسه و افزایش شمارنده حساب نمی‌شود. پاسخ با تلورانس یک خانه پذیرفته است.", 0, 24, 11, 13, ["یک سطر چهارتایی: 4 خواندن", "دو سطر چهارتایی: 8 خواندن"]),
"جدول jagged با سطرهای [2,4]، [] و [6] بساز. مجموع هر سطر را با foreach و سپس با index محاسبه کن؛ نتیجه‌ها برابر باشند. آخرین عنصر سطر غیرخالی را با ^1 بخوان.",
'int[][] rows = { new[] {2,4}, Array.Empty<int>(), new[] {6} };\nforeach (int[] row in rows)\n{\n    int first=0; foreach(int n in row) first+=n;\n    int second=0; for(int i=0;i<row.Length;i++) second+=row[i];\n    Console.WriteLine($"{first},{second}");\n    if(row.Length>0) Console.WriteLine(row[^1]);\n}',
"جمع سطرها 6،0،6 باشد. سطر خالی خطا ندهد و دو روش برابر باشند. ^1 فقط برای سطر غیرخالی به کار رود.")
